arguments.command:
python -c "
import parse

fmt = '''letters: {:w}
non-letters: {:W}
whitespace: \"{ :s}\"
non-whitespace: \t{:S}\n
digits: {:d}
non-digits: {:D}
numbers with thousands: {:n}
fixed-point: {:f}
floating-point: {:e}
general numbers: {:g} {:g}
binary: {:b}
octal: {:o}
hex: {:x}
final value: {}'''
data = '''letters: abcdef_GHIJLK
non-letters: !@#%\$ *^%
whitespace: \"   \t\n\"
non-whitespace: \tabc\n
digits: 0xabcdef
non-digits: abcdef
numbers with thousands: 1.000.000
fixed-point: 0.00001
floating-point: NAN
general numbers: 1.1e10 nan
binary: 0B1000
octal: 0O1000
hex: 0X1000
final value: spam'''

try:
    r = parse.parse(fmt, data)
    print('result:', r)
except Exception as e:
    import traceback
    traceback.print_exc()
" 2>&1 | grep -v SyntaxWarning
